MATCH (s:PlantItem {tag: 'TK-6-1'}), (t:PlantItem {tag: 'T-42-2'})
RETURN s.tag AS source_tag, t.tag AS destination_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*]->(t)
         WHERE all(n IN nodes(p) WHERE coalesce(n.tag, '') <> 'CHV-14-2')
       } AS can_flow_without_CHV_14_2

MATCH (s:PlantItem {tag: 'P-15-1'}), (t:PlantItem {tag: 'TK-28-3'})
